1	import type { Locator, Page } from '@playwright/test';
2	import { test, expect } from './fixtures';
3	import { MESSAGES } from '../../src/messages';
4	
5	// Stage 8 hardening: the CLAUDE.md §12 edge sweep, automated (E-EDGE.1..E-EDGE.9).
6	// Rules: A-12 (empty/spaces), A-13 (number format), A-14 (negative), A-15 (check order), A-16 (M-3), A-18 (lone "." / "-").
7	// Messages are quoted exactly as in docs/user-stories.md; a check against messages.ts guards the two from drifting apart.
8	
9	const M1 = 'Enter marks earned and total marks possible to see the score.';
10	const M2 = 'Enter a pass mark to see whether this is a pass or a fail.';
11	const M3 = 'The score will appear once every entry is valid.';
12	const PASS = 'Pass';
13	const FAIL = 'Fail';
14	
15	type Field = 'earned' | 'total' | 'pass';
16	const FIELDS: ReadonlyArray<Field> = ['earned', 'total', 'pass'];
17	
18	const NOT_NUMBER: Record<Field, string> = {
19	  earned: 'Marks earned must be a number, like 17.5.',
20	  total: 'Total marks possible must be a number, like 23.',
21	  pass: 'Pass mark must be a number, like 70.',
22	};
23	const NEGATIVE: Record<Field, string> = {
24	  earned: "Marks earned can't be negative.",
25	  total: "Total marks possible can't be negative.",
26	  pass: "Pass mark can't be negative.",
27	};
28	
29	/** Valid values for the other two fields, so each field's own outcome is visible. */
30	const BASE: Record<Field, string> = { earned: '17.5', total: '23', pass: '70' };
31	
32	/** Words that must never reach the screen (CLAUDE.md §11). */
33	const FORBIDDEN = /NaN|Infinity|undefined/;
34	
35	interface Card {
36	  inputs: Record<Field, Locator>;
37	  result: Locator;
38	  resultBody: Locator;
39	  score: Locator;
40	  verdict: Locator;
41	  gap: Locator;
42	}
43	
44	function card(page: Page): Card {
45	  const result = page.getByRole('region', { name: MESSAGES['M-39'] });
46	  return {
47	    inputs: {
48	      earned: page.getByLabel(MESSAGES['M-34'], { exact: true }),
49	      total: page.getByLabel(MESSAGES['M-35'], { exact: true }),
50	      pass: page.getByLabel(MESSAGES['M-36'] + MESSAGES['M-37'], { exact: true }),
51	    },
52	    result,
53	    resultBody: result.locator('.result-body'),
54	    score: result.locator('.score'),
55	    verdict: result.locator('.verdict'),
56	    gap: result.locator('.gap'),
57	  };
58	}
59	
60	async function setAll(c: Card, values: Record<Field, string>): Promise<void> {
61	  for (const field of FIELDS) await c.inputs[field].fill(values[field]);
62	}
63	
64	async function errorSlot(page: Page, input: Locator): Promise<Locator> {
65	  const id = await input.getAttribute('aria-describedby');
66	  expect(id).toBeTruthy();
67	  return page.locator(`#${id}`);
68	}
69	
70	/** Each field shows exactly its expected message (or none), with aria-invalid only while in error. */
71	async function expectFieldErrors(page: Page, c: Card, errors: Partial<Record<Field, string>>): Promise<void> {
72	  for (const field of FIELDS) {
73	    const input = c.inputs[field];
74	    const slot = await errorSlot(page, input);
75	    const text = errors[field];
76	    if (text === undefined) {
77	      await expect(slot).toHaveText('');
78	      await expect(input).not.toHaveAttribute('aria-invalid', 'true');
79	    } else {
80	      await expect(slot).toHaveText(text);
81	      await expect(input).toHaveAttribute('aria-invalid', 'true');
82	    }
83	  }
84	}
85	
86	/** Every state: the result area is never blank and no visible text holds NaN, Infinity or undefined. */
87	async function expectSane(page: Page, c: Card): Promise<void> {
88	  await expect(c.resultBody).not.toHaveText('');
89	  await expect(c.resultBody).not.toHaveText(FORBIDDEN);
90	  await expect(page.locator('body')).not.toHaveText(FORBIDDEN);
91	  for (const field of FIELDS) {
92	    await expect(await errorSlot(page, c.inputs[field])).not.toHaveText(FORBIDDEN);
93	  }
94	}
95	
96	async function expectIdle(page: Page, c: Card): Promise<void> {
97	  await expect(c.resultBody).toHaveText(M1);
98	  await expect(c.score).toHaveCount(0);
99	  await expectFieldErrors(page, c, {});
100	  await expectSane(page, c);
101	}
102	
103	async function expectErrorState(page: Page, c: Card, errors: Partial<Record<Field, string>>): Promise<void> {
104	  await expectFieldErrors(page, c, errors);
105	  await expect(c.resultBody).toHaveText(M3);
106	  await expect(c.score).toHaveCount(0);
107	  await expect(c.verdict).toHaveCount(0);
108	  await expect(c.gap).toHaveCount(0);
109	  await expectSane(page, c);
110	}
111	
112	async function expectOutcome(page: Page, c: Card, score: string, verdict: string): Promise<void> {
113	  await expect(c.score).toHaveText(score);
114	  await expect(c.verdict).toHaveText(verdict);
115	  await expect(c.gap).toHaveCount(1);
116	  await expectFieldErrors(page, c, {});
117	  await expectSane(page, c);
118	}
119	
120	/** The page never scrolls sideways. */
121	async function expectNoHorizontalScroll(page: Page): Promise<void> {
122	  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
123	  expect(overflow).toBeLessThanOrEqual(0);
124	}
