130	test('E-EDGE.0 the quoted messages match the messages.ts catalogue', () => {
131	  expect([M1, M2, M3, PASS, FAIL]).toEqual([MESSAGES['M-1'], MESSAGES['M-2'], MESSAGES['M-3'], MESSAGES['M-4'], MESSAGES['M-5']]);
132	  expect(NOT_NUMBER).toEqual({ earned: MESSAGES['M-12'], total: MESSAGES['M-16'], pass: MESSAGES['M-21'] });
133	  expect(NEGATIVE).toEqual({ earned: MESSAGES['M-13'], total: MESSAGES['M-17'], pass: MESSAGES['M-22'] });
134	});
