136	test('E-EDGE.1 whitespace-only or a lone "." in any field is empty: M-1 (earned/total) or "76.0%" + M-2 (pass), never an error (A-12, A-18)', async ({ page }) => {
137	  const c = card(page);
138	  for (const blank of ['   ', '\t', '.', ' . ']) {
139	    for (const field of ['earned', 'total'] as const) {
140	      await setAll(c, { ...BASE, [field]: blank });
141	      await expectIdle(page, c);
142	    }
143	    await setAll(c, { ...BASE, pass: blank });
144	    await expect(c.score).toHaveText('76.0%');
145	    await expect(c.result).toContainText(M2);
146	    await expect(c.verdict).toHaveCount(0);
147	    await expect(c.gap).toHaveCount(0);
148	    await expectFieldErrors(page, c, {});
149	    await expectSane(page, c);
150	  }
151	});
152	
153	test('E-EDGE.2 a lone "-" or "-." in any field shows that field\'s can\'t-be-negative message and M-3 (A-14, A-18)', async ({ page }) => {
154	  const c = card(page);
155	  for (const raw of ['-', '-.', ' - ']) {
156	    for (const field of FIELDS) {
157	      await setAll(c, { ...BASE, [field]: raw });
158	      await expectErrorState(page, c, { [field]: NEGATIVE[field] });
159	    }
160	  }
161	  // Recovery: the error clears as soon as the field is valid again.
162	  await setAll(c, BASE);
163	  await expectOutcome(page, c, '76.0%', PASS);
164	});
165	
166	test('E-EDGE.3 a 400-digit number in each field gives that field\'s range message, no NaN/Infinity, no sideways scroll', async ({ page }) => {
167	  const c = card(page);
168	  const long = '9'.repeat(400);
169	  const cases: Array<[Field, Partial<Record<Field, string>>]> = [
170	    ['earned', { earned: "Marks earned can't be more than the total marks possible." }],
171	    ['total', { total: "Total marks possible can't be more than 1,000,000." }],
172	    ['pass', { pass: "Pass mark can't be more than 100." }],
173	  ];
174	  for (const width of [320, 1280]) {
175	    await page.setViewportSize({ width, height: 800 });
176	    for (const [field, errors] of cases) {
177	      await setAll(c, { ...BASE, [field]: long });
178	      await expect(c.inputs[field]).toHaveValue(long);
179	      await expectErrorState(page, c, errors);
180	      await expectNoHorizontalScroll(page);
181	    }
182	    // 400 digits with a decimal tail: too many decimal places is checked before range (A-15).
183	    await setAll(c, { ...BASE, earned: `${long}.123` });
184	    await expectErrorState(page, c, { earned: 'Marks earned can have at most 2 decimal places.' });
185	    await expectNoHorizontalScroll(page);
186	    // A long non-number: not-a-number message, the error text wraps inside the card.
187	    await setAll(c, { ...BASE, total: `${long}x` });
188	    await expectErrorState(page, c, { total: NOT_NUMBER.total });
189	    await expectNoHorizontalScroll(page);
190	  }
191	});
192	
193	/** Pasted values: rejected ones get that field's not-a-number message; " 17.5 " and "007" are accepted (A-13). */
194	const REJECTED = ['$17', '17,5', '1e400', '+5'];
195	
196	async function pasteCases(page: Page, c: Card, put: (field: Field, raw: string) => Promise<void>): Promise<void> {
197	  for (const field of FIELDS) {
198	    for (const raw of REJECTED) {
199	      await setAll(c, BASE);
200	      await put(field, raw);
201	      await expect(c.inputs[field]).toHaveValue(raw);
202	      await expectErrorState(page, c, { [field]: NOT_NUMBER[field] });
203	    }
204	  }
205	
206	  // " 17.5 " is 17.5 in every field (spaces ignored).
207	  await setAll(c, BASE);
208	  await put('earned', ' 17.5 ');
209	  await expectOutcome(page, c, '76.0%', PASS);
210	  await setAll(c, BASE);
211	  await put('total', ' 17.5 ');
212	  await expectOutcome(page, c, '100.0%', PASS);
213	  await setAll(c, BASE);
214	  await put('pass', ' 17.5 ');
215	  await expectOutcome(page, c, '76.0%', PASS);
216	
217	  // "007" is 7.
218	  await setAll(c, BASE);
219	  await put('earned', '007');
220	  await expectOutcome(page, c, '30.4%', FAIL);
221	  await setAll(c, { ...BASE, earned: '7' });
222	  await put('total', '007');
223	  await expectOutcome(page, c, '100.0%', PASS);
224	  await setAll(c, BASE);
225	  await put('pass', '007');
226	  await expectOutcome(page, c, '76.0%', PASS);
227	}
228	
229	test('E-EDGE.4 pasted values via fill: "$17", "17,5", "1e400", "+5" → not-a-number per field; " 17.5 " and "007" (= 7) accepted', async ({ page }) => {
230	  const c = card(page);
231	  await pasteCases(page, c, (field, raw) => c.inputs[field].fill(raw));
232	});
233	
234	test('E-EDGE.5 pasted values via keyboard.insertText behave exactly like fill', async ({ page }) => {
235	  const c = card(page);
236	  await pasteCases(page, c, async (field, raw) => {
237	    await c.inputs[field].fill('');
238	    await c.inputs[field].focus();
239	    await page.keyboard.insertText(raw);
240	  });
241	});
