243	test('E-EDGE.6 pressing Enter 5 times in each field changes nothing (result, error and idle states)', async ({ page }) => {
244	  const c = card(page);
245	  const url = page.url();
246	
247	  async function pressEnterEverywhere(): Promise<void> {
248	    for (const field of FIELDS) {
249	      await c.inputs[field].focus();
250	      for (let i = 0; i < 5; i += 1) await page.keyboard.press('Enter');
251	    }
252	  }
253	
254	  // Result state.
255	  await setAll(c, BASE);
256	  await expectOutcome(page, c, '76.0%', PASS);
257	  const resultText = (await c.resultBody.textContent()) ?? '';
258	  await pressEnterEverywhere();
259	  await expect(c.resultBody).toHaveText(resultText);
260	  await expectOutcome(page, c, '76.0%', PASS);
261	  for (const field of FIELDS) await expect(c.inputs[field]).toHaveValue(BASE[field]);
262	  expect(page.url()).toBe(url);
263	
264	  // Error state.
265	  await setAll(c, { ...BASE, earned: 'abc' });
266	  await pressEnterEverywhere();
267	  await expectErrorState(page, c, { earned: NOT_NUMBER.earned });
268	  await expect(c.inputs.earned).toHaveValue('abc');
269	
270	  // Idle state.
271	  await setAll(c, { earned: '', total: '', pass: '70' });
272	  await pressEnterEverywhere();
273	  await expectIdle(page, c);
274	  expect(page.url()).toBe(url);
275	});
276	
277	test('E-EDGE.7 reload after a result or an error returns to idle: empty fields, pass mark "70", M-1', async ({ page }) => {
278	  const c = card(page);
279	  for (const values of [BASE, { ...BASE, total: '0' }, { ...BASE, earned: '-' }]) {
280	    await setAll(c, values);
281	    await page.reload();
282	    await expect(c.inputs.earned).toHaveValue('');
283	    await expect(c.inputs.total).toHaveValue('');
284	    await expect(c.inputs.pass).toHaveValue('70');
285	    await expectIdle(page, c);
286	  }
287	});
