289	/** Reads every error slot and the result body right after a key, before any later render could hide a flash. */
290	async function snapshot(page: Page): Promise<{ errors: string[]; result: string; invalid: number }> {
291	  return page.evaluate(() => ({
292	    errors: Array.from(document.querySelectorAll('.field-error'), (n) => n.textContent ?? ''),
293	    result: document.querySelector('.result-body')?.textContent ?? '',
294	    invalid: document.querySelectorAll('[aria-invalid="true"]').length,
295	  }));
296	}
297	
298	test('E-EDGE.8 typing "17.5" and ".5" key by key in each field never flashes an error mid-number', async ({ page }) => {
299	  const c = card(page);
300	  // While total is typed, marks earned is "0.5" so the partial total "1" is not a genuine "more than the total" error.
301	  const others: Record<Field, string> = { ...BASE, earned: '0.5' };
302	  for (const field of FIELDS) {
303	    for (const value of ['17.5', '.5']) {
304	      await setAll(c, { ...(field === 'total' ? others : BASE), [field]: '' });
305	      await c.inputs[field].focus();
306	      for (const key of value) {
307	        await page.keyboard.type(key);
308	        const s = await snapshot(page);
309	        expect(s.errors, `after "${key}" in ${field}`).toEqual(['', '', '']);
310	        expect(s.invalid).toBe(0);
311	        expect(s.result).not.toContain(M3);
312	        expect(s.result).not.toBe('');
313	        expect(s.result).not.toMatch(FORBIDDEN);
314	      }
315	      await expect(c.inputs[field]).toHaveValue(value);
316	      await expectFieldErrors(page, c, {});
317	      await expectSane(page, c);
318	    }
319	  }
320	});
321	
322	test('E-EDGE.9 states never show NaN, Infinity or undefined and the result area is never blank', async ({ page }) => {
323	  const c = card(page);
324	  const sweep: Array<Record<Field, string>> = [
325	    { earned: '', total: '', pass: '' },
326	    { earned: '0', total: '0', pass: '0' },
327	    { earned: '0', total: '0.01', pass: '0' },
328	    { earned: '0.01', total: '1000000', pass: '100' },
329	    { earned: '1000000', total: '1000000', pass: '100' },
330	    { earned: '-0', total: '-0', pass: '-0' },
331	    { earned: '1e400', total: 'Infinity', pass: 'NaN' },
332	    { earned: '1.2.3', total: '..', pass: '--5' },
333	    { earned: '0.', total: '5.', pass: '.0' },
334	    { earned: '17.5', total: '', pass: '' },
335	  ];
336	  for (const values of sweep) {
337	    await setAll(c, values);
338	    // Inputs may echo what was typed; the rendered output must not.
339	    await expect(c.resultBody).not.toHaveText('');
340	    await expect(c.resultBody).not.toHaveText(FORBIDDEN);
341	    for (const field of FIELDS) await expect(await errorSlot(page, c.inputs[field])).not.toHaveText(FORBIDDEN);
342	    await expect(page.getByRole('status')).not.toHaveText(FORBIDDEN);
343	  }
344	});
